// S-003 TK-007: every color token in app/theme/tokens.css equals the recorded
// Grill Board token in ../grill-board/theme/tokens.json (DDR-000Y).
//
// The theme block of tokens.css (light, manual dark, system dark and the
// .tone/.h-* mixes) is generated by scripts/gen-tokens.mjs and sits between
// two markers. The check is a byte-for-byte comparison of that block with the
// generator's output, plus a scan of the rest of the file: no recorded token
// name is declared there and no color-like value appears. Comparing text
// rather than parsing CSS closes the parser-loophole class Codex kept finding
// on PR #32 (duplicates, !important, var() spacing, nested media).
//
// Limit: tokens.json records colors and mixes only. Type and spacing tokens
// are hand-written outside the markers and are not compared; tokens.test.mjs
// still forbids any color, type or spacing literal outside tokens.css.
// Vercel builds with root directory site/, so ../grill-board is absent there;
// this check runs in the local `npm test` only.
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { BEGIN, END, CSS_PATH, JSON_PATH, generate } from '../scripts/gen-tokens.mjs';

const json = JSON.parse(readFileSync(JSON_PATH, 'utf8'));
const css = readFileSync(CSS_PATH, 'utf8');

const count = (text, s) => text.split(s).length - 1;
const recordedNames = () => [...new Set([
  ...Object.keys(json.themes.dark), ...Object.keys(json.themes.light),
  ...Object.values(json.mixes).flatMap((d) => Object.keys(d)),
])];
const esc = (s) => s.replace(/[-[\]().*+?^$|\\]/g, '\\$&');
const COLOR_LITERAL = /#[0-9a-f]{3,8}\b|\b(?:rgba?|hsla?|hwb|lab|lch|oklab|oklch|color|color-mix|light-dark)\s*\(/i;

// Every problem with a tokens.css text, as readable strings; [] means it passes.
export function problems(text) {
  const out = [];
  // (b) each marker exactly once, BEGIN first.
  for (const [name, marker] of [['BEGIN', BEGIN], ['END', END]]) {
    const n = count(text, marker);
    if (n !== 1) out.push(`${name} marker appears ${n} times, not once`);
  }
  if (out.length) return out;
  const b = text.indexOf(BEGIN);
  const e = text.indexOf(END);
  if (e < b) return ['END marker comes before BEGIN'];
  // The markers must sit at stylesheet top level: no brace left open before BEGIN or after END.
  const depth = (t) => { let d = 0; for (const ch of t.replace(/\/\*[\s\S]*?\*\//g, '')) { if (ch === '{') d++; else if (ch === '}') d--; } return d; };
  if (depth(text.slice(0, b)) !== 0 || depth(text.slice(e + END.length)) !== 0) out.push('the generated block is not at stylesheet top level: a rule or at-rule encloses the markers');
  // (a) the block equals the generator's output byte for byte.
  const block = text.slice(b + BEGIN.length, e);
  const expected = generate(json);
  if (block !== expected) {
    const a = block.split('\n');
    const x = expected.split('\n');
    const i = a.findIndex((line, k) => line !== x[k]);
    const at = i === -1 ? a.length : i;
    out.push(`theme block differs from scripts/gen-tokens.mjs output at block line ${at + 1}: found ${JSON.stringify(a[at])}, expected ${JSON.stringify(x[at])}; run npm run tokens:gen`);
  }
  // (c) outside the markers: no recorded token declared, no color-like value.
  const outside = (text.slice(0, b) + '\n' + text.slice(e + END.length)).replace(/\/\*[\s\S]*?\*\//g, '');
  const names = recordedNames();
  for (const name of names) {
    if (new RegExp(`${esc(name)}\\s*:`).test(outside)) out.push(`recorded token ${name} is declared outside the generated block`);
  }
  const usesRecorded = new RegExp(`var\\s*\\(\\s*(?:${names.map(esc).join('|')})(?![\\w-])`);
  for (const m of outside.matchAll(/([\w-]+)\s*:\s*([^;{}]+)(?=[;}])/g)) {
    const [, prop, raw] = m;
    const value = raw.trim();
    if (COLOR_LITERAL.test(value)) out.push(`${prop}: ${value} is a color literal outside the generated block`);
    else if (usesRecorded.test(value)) out.push(`${prop}: ${value} uses a recorded color token outside the generated block`);
    else if (/^[a-z]+$/i.test(value)) out.push(`${prop}: ${value} is a bare keyword (possibly a named color) outside the generated block`);
  }
  return out;
}

test('the generator covers every recorded token in both themes and every mix', () => {
  const block = generate(json);
  for (const theme of ['light', 'dark']) {
    for (const [name, value] of Object.entries(json.themes[theme])) {
      assert.ok(block.includes(`  ${name}: ${value}; /* ${json.meanings[name]} */`), `${theme} ${name}`);
    }
  }
  for (const [sel, decls] of Object.entries(json.mixes)) {
    assert.ok(block.includes(`${sel} {`), sel);
    for (const [name, value] of Object.entries(decls)) assert.ok(block.includes(`${name}: ${value};`), `${sel} ${name}`);
  }
});

test('tokens.css carries the generated theme block exactly and nothing recorded outside it', () => {
  assert.deepEqual(problems(css), []);
});

// Planted faults, each on an in-memory copy of tokens.css.
const [head, rest] = [css.slice(0, css.indexOf(END)), css.slice(css.indexOf(END))];
const inBlock = (from, to) => {
  assert.ok(head.includes(from), `plant site ${from} not found in the generated block`);
  return head.replace(from, to) + rest;
};
const fails = (text, label, pattern) => {
  const found = problems(text);
  assert.ok(found.length, `${label}: not reported`);
  if (pattern) assert.ok(found.some((p) => pattern.test(p)), `${label}: ${found.join(' | ')}`);
};

test('an edit inside the generated block fails', () => {
  fails(inBlock('  --heat: #F04E12;', '  --heat: #F04E12;\n  --stray: #FF00FF;'), 'stray color', /theme block differs/);
  fails(inBlock('  --owner: #4C9BE8;', '  --owner: #4C9BE9;'), 'changed dark value', /theme block differs/);
  fails(inBlock('    --agent: #3DBE5A;', '    --agent: #3DBE5B;'), 'changed system-dark value', /theme block differs/);
  fails(inBlock('  --returned: #A66BE0; /* It came back for rework */\n  --soft-pct: 22%;', '  --soft-pct: 22%;'), 'missing light token', /theme block differs/);
  fails(inBlock('  --hue: var(--line-strong);', '  --hue: var(--line);'), 'changed mix', /theme block differs/);
  fails(inBlock('  --hue: var(--line-strong);', '  --hue: var(--LINE-STRONG);'), 'wrongly cased reference', /theme block differs/);
  fails(inBlock('  --heat: #F04E12;', '  --heat: #FF00FF !important; --heat: #F04E12;'), 'duplicate and !important', /theme block differs/);
  fails(inBlock('  --worth: #F5C400;', '  --worth: #F5C400 !important;'), 'single !important', /theme block differs/);
  // Codex 4435952642: a space between var and its parenthesis.
  fails(inBlock('  --hue: var(--line-strong);', '  --hue: var (--line-strong);'), 'var (--x)', /theme block differs/);
  // Codex 4435952645: the system-dark rule nested in another media query.
  const sysDark = head.slice(head.indexOf('@media (prefers-color-scheme: dark) {'));
  const sysDarkEnd = sysDark.indexOf('\n}\n') + 2;
  const wrapped = sysDark.slice(0, sysDarkEnd);
  fails(inBlock(wrapped, `@media (min-width: 2000px) {\n${wrapped}\n}`), 'system-dark rule wrapped in @media (min-width: 2000px)', /theme block differs/);
});

test('a recorded token or color outside the generated block fails', () => {
  fails(css + '\n.h-extra { --hue: var(--heat); }\n', 'unrecorded mix rule', /--hue is declared outside/);
  fails(css + '\n:root { --soft-pct: 0%; }\n', 'out-of-place percentage override', /--soft-pct is declared outside/);
  fails(css + '\n:root { --heat: var(--worth, red); }\n', 'var() with a fallback', /--heat is declared outside/);
  fails(css + '\n:root { --x: var( --worth ); }\n', 'var() with inner whitespace', /uses a recorded color token/);
  fails(css + '\n:root { --x: var (--worth); }\n', 'var () outside', /uses a recorded color token/);
  fails(css + '\n:root { --x: red; }\n', 'named color', /bare keyword/);
  fails(css.replace('--space-4: 4px;', '--space-4: 4px;\n  --accent: #123456;'), 'color in the spacing block', /color literal/);
  const darkDecls = Object.entries(json.themes.dark).map(([k, v]) => `${k}: ${v};`).join(' ');
  fails(css + `\n@media (prefers-color-scheme: dark) { [data-theme="light"] { ${darkDecls} } }\n`, 'dark values scoped to light', /declared outside/);
  const lightDecls = Object.entries(json.themes.light).map(([k, v]) => `${k}: ${v};`).join(' ');
  fails(css + `\n[data-theme="light"] { ${lightDecls} }\n`, 'a second light rule', /declared outside/);
  // A recorded token redeclared right after the END marker.
  fails(css.replace(END, `${END}\n:root { --ground: #F7F7F7; }`), 'recorded token after END', /--ground is declared outside/);
});

test('missing, duplicated or reordered markers fail', () => {
  fails(css.replace(BEGIN, ''), 'no BEGIN', /BEGIN marker appears 0 times/);
  fails(css + `\n${END}\n`, 'two END markers', /END marker appears 2 times/);
  // Codex review on PR #32: wrapping the whole marked block in an at-rule from outside the markers.
  fails(css.replace(BEGIN, `@media (min-width: 2000px) {\n${BEGIN}`).replace(END, `${END}\n}`), 'block wrapped from outside', /top level/);
  const b = css.indexOf(BEGIN);
  const e = css.indexOf(END);
  const swapped = css.slice(0, b) + END + css.slice(b + BEGIN.length, e) + BEGIN + css.slice(e + END.length);
  fails(swapped, 'END before BEGIN', /END marker comes before BEGIN/);
});
